mapper.select:
SELECT  FROM cw_semantic_cache
WHERE scope_id = #{scopeId}
  AND config_generation = #{configGeneration}
  AND intent = #{intent}
  AND created_at_ms >= #{notBeforeMs}
ORDER BY last_hit_at_ms DESC
LIMIT #{limit}

mapper.update:
UPDATE cw_semantic_cache
SET hit_count = hit_count + 1, last_hit_at_ms = #{hitAtMs}
WHERE id = #{id}

mapper.select:
SELECT last_hit_at_ms FROM cw_semantic_cache
WHERE scope_id = #{scopeId}
  AND config_generation = #{configGeneration}
ORDER BY last_hit_at_ms DESC
LIMIT 1 OFFSET #{keepSize}

mapper.delete:
DELETE FROM cw_semantic_cache
WHERE scope_id = #{scopeId}
  AND config_generation = #{configGeneration}
  AND last_hit_at_ms <= #{thresholdMs}

mapper.select:
SELECT id, scope_id, intent, question, answer, hit_count, created_at_ms, last_hit_at_ms
FROM cw_semantic_cache
WHERE scope_id = #{scopeId}
ORDER BY hit_count DESC, last_hit_at_ms DESC
LIMIT #{limit}
